package render

import "strings"

// header opens every generated Markdown file. It says where the file comes
// from and where manual edits belong, so nobody edits it by hand and loses
// the change at the next regeneration. It cannot quote the custom markers
// literally, because an HTML comment cannot contain another one.
var header = []string{
	"<!-- Generated by cyanotype from cyanotype.yaml; regenerating replaces this file.",
	"Change rules in cyanotype.yaml (custom_rules for your own), or write between",
	"cyanotype:custom markers, which regeneration keeps. -->",
}

// document is a generated Markdown file before its protected sections are
// put back: a preamble, such as the title, followed by sections in output
// order.
type document struct {
	// preamble holds the lines right after the header, such as "# name" or
	// an import like "@AGENTS.md".
	preamble []string
	sections []section
}

// section is one "## title" part of a document.
type section struct {
	title string
	// body holds the lines under the heading; an empty string separates
	// paragraphs and lists.
	body []string
}

// render returns the document as Markdown with the protected blocks from the
// previous version of the file put back. A block returns to the end of the
// section it was in; a block above every section goes right after the
// preamble; a block whose section is no longer generated goes to the end of
// the file. Blocks that land in the same place keep their original order.
func (d document) render(blocks []customBlock) []byte {
	generated := make(map[string]bool, len(d.sections))
	for _, s := range d.sections {
		generated[s.title] = true
	}
	var top, orphans []customBlock
	inSection := make(map[string][]customBlock)
	for _, b := range blocks {
		switch {
		case b.anchor == "":
			top = append(top, b)
		case generated[b.anchor]:
			inSection[b.anchor] = append(inSection[b.anchor], b)
		default:
			orphans = append(orphans, b)
		}
	}

	// Each part is a group of lines, separated from the next by one blank line.
	parts := [][]string{header}
	if len(d.preamble) > 0 {
		parts = append(parts, d.preamble)
	}
	parts = appendBlocks(parts, top)
	for _, s := range d.sections {
		parts = append(parts, []string{"## " + s.title})
		if len(s.body) > 0 {
			parts = append(parts, s.body)
		}
		parts = appendBlocks(parts, inSection[s.title])
	}
	parts = appendBlocks(parts, orphans)

	var b strings.Builder
	for i, p := range parts {
		if i > 0 {
			b.WriteByte('\n')
		}
		for _, line := range p {
			b.WriteString(line)
			b.WriteByte('\n')
		}
	}
	return []byte(b.String())
}

func appendBlocks(parts [][]string, blocks []customBlock) [][]string {
	for _, b := range blocks {
		parts = append(parts, b.lines)
	}
	return parts
}
